  function renderStories(rows){ const grid=$('story-grid'); if(!grid)return; if(!rows?.length){grid.innerHTML='<p class="empty-state">New stories are on their way. Please visit again soon.</p>';return;} grid.innerHTML=rows.map((a,i)=>`<article class="story-card ${i===0?'featured':''}" data-category="${esc(a.category||'All')}" data-search="${esc((a.title||'')+' '+(a.excerpt||''))}"><a class="story-image ${['image-one','image-two','image-three'][i%3]}" href="article.html?id=${encodeURIComponent(a.id)}">${a.cover_image?`<img src="${esc(a.cover_image)}" alt="" loading="lazy">`:`<span class="image-word">${esc((a.title||'STORY').slice(0,28))}</span>`}</a><div class="story-meta"><span>${esc(a.category||'Journal')}</span><span>Thoughts & Stories</span></div><h3><a href="article.html?id=${encodeURIComponent(a.id)}">${esc(a.title)}</a></h3><p>${esc(a.excerpt||'')}</p><a class="read-link" href="article.html?id=${encodeURIComponent(a.id)}">Read story ↗</a></article>`).join(''); }
