  function applyBookFilter(filter){document.querySelectorAll('#books-grid .bookzone-card').forEach(card=>card.hidden=filter!=='all'&&card.dataset.access!==filter);document.querySelectorAll('[data-book-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.bookFilter===filter));}
