    layer.hidden=false;$('member-site')?.querySelector('main')?.classList.add('detail-open');
    content.querySelectorAll('[data-book-panel]').forEach(btn=>btn.addEventListener('click',()=>{content.querySelectorAll('[data-book-panel]').forEach(x=>x.classList.toggle('selected',x===btn));$('book-reviews-panel').hidden=btn.dataset.bookPanel!=='reviews';$('book-chat-panel').hidden=btn.dataset.bookPanel!=='chat';if(btn.dataset.bookPanel==='chat')loadBookChat(b.id);}));
