    $('book-chat-form').addEventListener('submit',async e=>{e.preventDefault();const user=await userNow();if(!user){say('book-chat-status','Please sign in to join this book discussion.');return;}const text=$('book-chat-text').value.trim();if(!text)return;const display=user.user_metadata?.display_name||user.user_metadata?.username||user.email?.split('@')[0]||'Reader';const {error}=await db.from('book_chat_messages').insert({book_id:b.id,user_id:user.id,display_name:display,body:text});say('book-chat-status',error?.message||'Message sent.');if(!error){$('book-chat-text').value='';await loadBookChat(b.id);}});
