  async function bookFunctionRequest(functionName, body){const {data:{session}}=await db.auth.getSession();const response=await fetch(`${window.SUPABASE_URL}/functions/v1/${functionName}`,{method:'POST',headers:{'content-type':'application/json','apikey':window.SUPABASE_ANON_KEY,...(session?.access_token?{authorization:`Bearer ${session.access_token}`}:{})},body:JSON.stringify({...body,...(body.bookId?{book_id:body.bookId}:{})})});let data={};try{data=await response.json();}catch{}return {status:response.status,data};}
  async function bookAccessRequest(bookId){const result=await bookFunctionRequest('book-access',{bookId});const d=result.data||{};return {status:result.status,data:{...d,readUrl:d.readUrl||d.read_url||d.url||null,downloadUrl:d.downloadUrl||d.download_url||d.readUrl||d.read_url||d.url||null,alreadyOwned:d.alreadyOwned??d.already_owned??false}};}
  function showBookReader(data){const panel=$('book-access-panel');if(!panel)return;panel.innerHTML=`<div class="book-reader-actions"><a class="button button-dark" href="${esc(data.readUrl)}" target="_blank" rel="noopener">Open book PDF ↗</a><a class="button button-outline" href="${esc(data.downloadUrl||data.readUrl)}" target="_blank" rel="noopener" download>Download book</a></div><p class="form-note">Your secure reading link is temporary. Your purchase remains saved in your account, so you can reopen or download the book whenever you return.</p><iframe class="book-pdf-frame" title="${esc(data.title||activeBook?.title||'Book PDF')}" src="${esc(data.readUrl)}#toolbar=1" loading="lazy"></iframe>`;}
  async function loadBookAccess(book, poll=false){const panel=$('book-access-panel');if(!panel)return;const user=await userNow().catch(()=>null);if(!user){panel.innerHTML=`<p class="form-note">Sign in or create a free member account to ${book.access_type==='purchase'?'purchase and access':'open'} this book.</p><button class="button button-dark" type="button" id="book-signin-required">Sign in to continue</button>`;$('book-signin-required')?.addEventListener('click',()=>$('account-open')?.click());return;}
    panel.innerHTML='<p class="form-note">Checking your book access…</p>';const result=await bookAccessRequest(book.id);
    if(result.status===200&&result.data.readUrl){showBookReader(result.data);return;}
    if(result.status===202&&poll){panel.innerHTML='<p class="form-note">Waiting for M-Pesa confirmation… Keep this page open. Your book will unlock automatically when payment is verified.</p>';return;}
    if(book.access_type==='purchase'){
      panel.innerHTML=`<form id="book-payment-form" class="book-payment-form"><p class="form-note">This is a paid title. Complete the M-Pesa payment to unlock it permanently on your account.</p><label for="book-payment-phone">Safaricom M-Pesa phone number</label><input id="book-payment-phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="0712345678" required><button class="button button-dark" type="submit">Pay KSh ${esc(book.price??'')} with M-Pesa</button><p class="form-note" id="book-payment-status" role="status">You will receive an STK Push prompt on your phone.</p></form>`;
      $('book-payment-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;say('book-payment-status','Sending M-Pesa payment request…');try{const payment=await bookFunctionRequest('create-book-payment',{bookId:book.id,phone:$('book-payment-phone').value.trim()});const data=payment.data||{};if(payment.status<200||payment.status>=300)throw new Error(data.error||'Could not start payment.');say('book-payment-status',data.message||'Check your phone and enter your M-Pesa PIN.');if(data.alreadyOwned){await loadBookAccess(book);return;}let attempts=0;const pollAccess=async()=>{attempts++;const check=await bookAccessRequest(book.id);if(check.status===200&&check.data.readUrl){showBookReader(check.data);return;}if((check.status===202||check.status===402)&&attempts<48){say('book-payment-status','Waiting for Safaricom to confirm your payment…');setTimeout(pollAccess,5000);return;}if(check.status===402){say('book-payment-status','No successful payment has been confirmed. If you cancelled the prompt, you can try again.');return;}if(attempts>=48){say('book-payment-status','Payment is still being confirmed. You can tap “Check my access” below in a moment.');const checkBtn=document.createElement('button');checkBtn.type='button';checkBtn.className='button button-outline';checkBtn.textContent='Check my access';checkBtn.onclick=()=>loadBookAccess(book,true);$('book-access-panel').append(checkBtn);}};setTimeout(pollAccess,5000);}catch(error){say('book-payment-status',error.message);}finally{button.disabled=false;}});
    }else if(result.status===202){panel.innerHTML='<p class="form-note">Your access is being prepared. Please try again shortly.</p>';}
    else {panel.innerHTML=`<p class="form-note">${esc(result.data.error||'This book PDF is not available yet.')}</p>`;}
  }
  async function loadBookComments(bookId){const box=$('book-comments-list');if(!box)return;const {data,error}=await db.from('book_comments').select('display_name,body,created_at,admin_reply').eq('book_id',bookId).eq('approved',true).order('created_at',{ascending:true});if(error){box.innerHTML='<p class="form-note">Reader comments are not available until the BookZone database setup is run.</p>';return;}box.innerHTML=(data||[]).map(c=>`<article class="reader-comment"><strong>${esc(c.display_name||'Reader')}</strong><p>${esc(c.body)}</p><small>${new Date(c.created_at).toLocaleString()}</small>${c.admin_reply?`<blockquote><b>Author reply</b><br>${esc(c.admin_reply)}</blockquote>`:''}</article>`).join('')||'<p class="empty-state">No comments yet. Be the first reader to share a thought.</p>';}
  async function loadBookChat(bookId){if(!db)return;const box=$('book-chat-messages');if(!box)return;const user=await userNow();if(!user){box.innerHTML='<p class="empty-state">Sign in to read and join this book discussion.</p>';return;}const {data,error}=await db.from('book_chat_messages').select('display_name,body,created_at').eq('book_id',bookId).order('created_at',{ascending:true}).limit(100);if(error){box.innerHTML='<p class="form-note">Book chat is unavailable until the BookZone database setup is run.</p>';return;}box.innerHTML=(data||[]).map(m=>`<article class="chat-message"><strong>${esc(m.display_name||'Reader')}</strong><p>${esc(m.body)}</p><small>${new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></article>`).join('')||'<p class="empty-state">Start the discussion. What stood out to you in this book?</p>';box.scrollTop=box.scrollHeight;if(bookChatRefresh)clearInterval(bookChatRefresh);bookChatRefresh=setInterval(()=>{if($('book-chat-panel')&&!$('book-chat-panel').hidden)loadBookChat(bookId);},12000);}
  async function loadVideos(adminMode=false){const target=$(adminMode?'admin-video-list':'public-video-grid');if(!target||!db)return;let q=db.from('video_items').select('*').order('created_at',{ascending:false});if(!adminMode)q=q.eq('published',true);const {data,error}=await q;if(error){target.innerHTML=`<p class="form-note">${esc(error.message)}. Run the BookZone and video setup SQL.</p>`;return;}target.innerHTML=(data||[]).map(v=>{const id=extractYoutubeId(v.video_url);const embed=id?`https://www.youtube-nocookie.com/embed/${id}`:'';const media=embed?`<div class="video-frame"><iframe src="${embed}" title="${esc(v.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div>`:`<div class="video-frame"><video controls playsinline preload="metadata" src="${esc(v.video_url)}" ${v.thumbnail_url?`poster="${esc(v.thumbnail_url)}"`:''}></video></div>`;return adminMode?`<div class="admin-item"><div><strong>${esc(v.title)}</strong><br><small>${v.published?'Published':'Hidden'}</small></div><div class="admin-actions"><button class="button button-outline button-small" data-video-toggle="${v.id}" data-value="${!v.published}">${v.published?'Hide':'Publish'}</button><button class="button button-outline button-small" data-video-delete="${v.id}" data-path="${esc(v.video_path||'')}">Delete</button></div></div>`:`<article class="video-card">${media}<div class="video-card-copy"><p class="eyebrow">THOUGHTS &amp; STORIES VIDEO STATION</p><h3>${esc(v.title)}</h3><p>${esc(v.description||'')}</p></div></article>`;}).join('')||'<p class="empty-state">Your videos will appear here once published from the administrator studio.</p>';if(adminMode){target.querySelectorAll('[data-video-toggle]').forEach(b=>b.onclick=async()=>{const {error}=await db.from('video_items').update({published:b.dataset.value==='true'}).eq('id',b.dataset.videoToggle);say('video-status',error?.message||'Video visibility updated.');await loadVideos(true);});target.querySelectorAll('[data-video-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this video entry?'))return;const path=b.dataset.path;if(path){const {error:storageError}=await db.storage.from('public-videos').remove([path]);if(storageError){say('video-status',storageError.message);return;}}const {error}=await db.from('video_items').delete().eq('id',b.dataset.videoDelete);say('video-status',error?.message||'Video deleted.');await loadVideos(true);});}}
  function extractYoutubeId(url){try{const u=new URL(url);if(u.hostname.includes('youtu.be'))return u.pathname.slice(1);if(u.hostname.includes('youtube.com'))return u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).pop();}catch(e){}return '';}
  async function loadSupportSection(){const box=$('support-content');if(!box||!db)return;const {data,error}=await db.from('donation_settings').select('*').eq('id',1).maybeSingle();if(error||!data||!data.enabled){box.innerHTML='<p class="empty-state">Support options will be available here soon.</p>';return;}box.innerHTML=`<div class="support-card"><h3>${esc(data.title||'Support the writing')}</h3><p>${esc(data.message||'Your contribution helps keep this independent publishing space active.')}</p>${data.mpesa_number?`<p><strong>M-Pesa:</strong> ${esc(data.mpesa_number)}</p>`:''}${data.payment_link?`<a class="button button-dark" href="${esc(data.payment_link)}" target="_blank" rel="noopener">Contribute securely ↗</a>`:''}</div>`;}
  async function getProfile(uid){const {data,error}=await db.from('profiles').select('id,display_name,role').eq('id',uid).maybeSingle();if(error)throw error;return data;}
  async function refreshAccountUI(){if(!db)return;const {data:{user}}=await db.auth.getUser();const sign=$('account-open'),join=$('join-open');if(user){if(sign){sign.textContent='My account';sign.onclick=async()=>{const p=await getProfile(user.id).catch(()=>null);alert(`${p?.display_name||user.email}\n${p?.role==='admin'?'Signed in with member and administrator access':'Signed in as a member'}`);};}if(join){join.textContent='Sign out';join.onclick=async()=>{await db.auth.signOut();location.reload();};}if(pAdminShortcut()&&await isAdmin().catch(()=>false))$('admin-shortcut').hidden=false;}else{if(sign)sign.textContent='Sign in';if(join)join.textContent='Create account';}}
