  async function adminGate(){const root=$('admin-root');if(!root)return; if(!db){$('admin-login').hidden=false;say('admin-login-status','Supabase configuration is missing.');return;}const user=await userNow().catch(()=>null);if(!user){$('admin-login').hidden=false;$('admin-denied').hidden=true;$('admin-workspace').hidden=true;return;}try{const ok=await isAdmin();if(!ok){$('admin-denied').hidden=false;$('admin-login').hidden=true;$('admin-workspace').hidden=true;return;}}catch(e){$('admin-denied').hidden=false;$('admin-login').hidden=true;$('admin-workspace').hidden=true;say('admin-denied-message',`Administrator verification failed: ${e.message}. Confirm the SQL migration and function permissions.`);return;} $('admin-login').hidden=true;$('admin-denied').hidden=true;$('admin-workspace').hidden=false;$('admin-signout').hidden=false;$('admin-email').textContent=user.email||'Administrator';await Promise.allSettled([listArticles(),listBooks(),loadProfile(),loadDonation(),loadComments(),loadMembers(),loadOverview(),loadAnalytics(),loadGallery(true),loadVideos(true)]);}
  async function listArticles(){const {data,error}=await db.from('articles').select('*').order('created_at',{ascending:false});if(error){say('article-status',error.message);return;}const box=$('article-list');box.innerHTML=(data||[]).map(a=>`<div class="admin-item"><div><strong>${esc(a.title)}</strong><br><small>${a.published?'Published':'Draft'} · ${esc(a.category||'Uncategorised')} · ${esc(a.slug||'')}</small></div><div class="admin-actions"><button class="button button-outline button-small" data-edit-article="${a.id}">Edit</button><button class="button button-outline button-small" data-delete-article="${a.id}">Delete</button></div></div>`).join('')||'<p>No articles yet.</p>';box.querySelectorAll('[data-edit-article]').forEach(b=>b.onclick=()=>editArticle(data.find(a=>a.id===b.dataset.editArticle)));box.querySelectorAll('[data-delete-article]').forEach(b=>b.onclick=()=>deleteArticle(b.dataset.deleteArticle));}
