  async function listBooks(){const {data,error}=await db.from('books').select('*').order('created_at',{ascending:false});if(error){say('book-status',error.message);return;}const box=$('book-list');box.innerHTML=(data||[]).map(b=>`<div class="admin-item"><div><strong>${esc(b.title)}</strong><br><small>${esc(b.author||'')} · ${b.access_type==='purchase'?'Paid · KSh '+esc(b.price??''):'Free'} · ${b.pdf_path?'PDF uploaded':'No PDF'} · ${b.published?'Visible':'Hidden'}</small></div><div class="admin-actions"><button class="button button-outline button-small" data-edit-book="${b.id}">Edit</button><button class="button button-outline button-small" data-delete-book="${b.id}">Delete</button></div></div>`).join('')||'<p>No books added yet.</p>';box.querySelectorAll('[data-edit-book]').forEach(x=>x.onclick=()=>{const b=data.find(v=>v.id===x.dataset.editBook);$('book-id').value=b.id;$('book-title').value=b.title||'';$('book-author').value=b.author||'';$('book-description').value=b.description||'';$('book-cover').value=b.cover_image||'';$('book-url').value=b.book_url||'';$('book-pdf-path').value=b.pdf_path||'';$('book-access-type').value=b.access_type||'free';$('book-price').value=b.price??'';$('book-review').value=b.review||'';$('book-rating').value=b.rating??'';$('book-published').checked=!!b.published;updateBookCoverPreview();showSection('books');});box.querySelectorAll('[data-delete-book]').forEach(x=>x.onclick=async()=>{if(confirm('Delete this book?')){const r=await db.from('books').delete().eq('id',x.dataset.deleteBook);say('book-status',r.error?.message||'Book deleted.');await listBooks();await loadHome();}});}
