  async function saveBook(e){e.preventDefault();const id=$('book-id').value,file=$('book-pdf-file')?.files?.[0];let pdfPath=$('book-pdf-path').value||null;const accessType=$('book-access-type').value;try{if(file){if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))throw new Error('Please choose a PDF file.');if(file.size>50*1024*1024)throw new Error('The PDF must be 50 MB or smaller.');const user=await userNow();if(!user)throw new Error('Administrator session expired. Please sign in again.');const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'-');pdfPath=`${user.id}/${crypto.randomUUID()}-${safeName}`;say('book-status','Uploading PDF securely…');const {error:uploadError}=await db.storage.from('paid-books').upload(pdfPath,file,{contentType:'application/pdf',upsert:false});if(uploadError)throw uploadError;}if(accessType==='purchase'&&!pdfPath)throw new Error('Upload the book PDF before saving a paid book. Paid PDFs must be stored privately.');const p={title:$('book-title').value.trim(),author:$('book-author').value.trim(),description:$('book-description').value.trim(),cover_image:$('book-cover').value.trim()||null,book_url:accessType==='free'?($('book-url').value.trim()||null):null,pdf_path:pdfPath,access_type:accessType,price:accessType==='purchase'&&$('book-price').value?Number($('book-price').value):null,purchase_url:null,review:$('book-review').value.trim(),rating:$('book-rating').value?Number($('book-rating').value):null,published:$('book-published').checked};if(accessType==='purchase'&&(!Number.isInteger(p.price)||p.price<1))throw new Error('Enter a whole-number price in Kenyan shillings.');const q=id?db.from('books').update(p).eq('id',id):db.from('books').insert(p);const {error}=await q;if(error)throw error;say('book-status','Book saved. The cover preview and secure PDF access are ready.');$('book-form').reset();$('book-id').value='';$('book-pdf-path').value='';updateBookCoverPreview();await listBooks();await loadHome();}catch(error){say('book-status',error.message||'Could not save this book.');}}
